/** Existing isolated branch only. Caller owns random schema; no global role changes. */
import {readFile} from 'node:fs/promises';import type pg from 'pg';
export function scopeServicePolicySql(sql:string,schema:string){if(!/^service_(?:policy|refund)_[a-f0-9]{24}$/.test(schema))throw Error('ISOLATED_SERVICE_SCHEMA_REQUIRED');return sql.replace(/\bzee\b/g,`"${schema}"`);}
export async function installServicePolicyPgSchema(client:pg.Client,schema:string,includeRefunds=false,includePolicy=true){
 const roles=(await client.query("SELECT rolname,pg_has_role(current_user,oid,'MEMBER') member FROM pg_roles WHERE rolname IN('zeeswap_api','zeeswap_worker','zeeswap_reader')")).rows;if(roles.length!==3||roles.some(r=>r.member!==true))throw Error('Existing isolated harness roles required');
 const files=['0001_core.sql','0002_transitions.sql','0003_boundary_hardening.sql','0004_observer_guards.sql','0005_source_liabilities.sql','0006_api_requests.sql','0007_observer_cycle.sql','0008_private_order_status.sql','0009_base_settlement.sql','0010_base_lease_renewal.sql','0011_reverse_escrow_preflight.sql','0012_reverse_delivery.sql','0013_source_refunds.sql','0014_targeted_g5_claims.sql','0017_native_circle_continuation.sql','0018_native_circle_replacement.sql','0019_root_native_circle_authorization.sql',...(includePolicy?['0020_bounded_testnet_service_policy.sql']:[]),...(includeRefunds?['0021_testnet_service_refunds.sql']:[])];let created=false;
 try{for(const file of files){const sql=(await readFile(new URL('../../migrations/'+file,import.meta.url),'utf8')).replace(/\r\n/g,'\n').replace(/^CREATE ROLE zeeswap_(api|worker|reader) NOLOGIN;\r?\n/gm,'').replace(/^GRANT zeeswap_api, zeeswap_worker, zeeswap_reader TO CURRENT_USER;\n/gm,'');await client.query(scopeServicePolicySql(sql,schema));if(file==='0001_core.sql')created=true;}}catch(e){if(created)await client.query(`DROP SCHEMA "${schema}" CASCADE`);throw e;}
}
